fn draw_signed(x: i32, y: i32, v: i32, rgb: i32, sc: i32) {
    if v < 0 {
        host::display::draw_char(x, y, 45, rgb, sc);
        host::display::draw_number(x + sc * 8, y, 0 - v, rgb, sc);
    } else {
        host::display::draw_number(x, y, v, rgb, sc);
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x0c0c0c);
    let base: i32 = h - 60;
    let deltas = [40, -15, 25, -30, 20];
    let bw: i32 = (w - 40) / 6;
    let mut c: i32 = 0;
    let mut i: i32 = 0;
    while i < 5 {
        let d: i32 = deltas[i];
        let n: i32 = c + d;
        let top: i32 = if d > 0 { n } else { c };
        let bh: i32 = if d > 0 { d } else { 0 - d };
        let col: i32 = if d > 0 { 0x30c060 } else { 0xd04040 };
        let x: i32 = 20 + i * bw;
        host::display::fill_rect(x + 4, base - top * 3, bw - 8, bh * 3, col);
        draw_signed(x + 4, base - top * 3 - 14, d, 0xc0c0c0, 1);
        host::display::draw_line(x + bw - 4, base - n * 3, x + bw + 4, base - n * 3, 0x808080);
        c = n;
        i = i + 1;
    }
    host::display::fill_rect(20 + 5 * bw + 4, base - c * 3, bw - 8, c * 3, 0xffffff);
    host::display::draw_string(20 + 5 * bw, base + 10, "TOTAL", 0x808080, 1);
    host::display::draw_number(20 + 5 * bw + 4, base - c * 3 - 14, c, 0xffffff, 1);
    host::display::draw_line(16, base, w - 16, base, 0x606060);
    host::display::present();
}
